    13	public class Api {
    14	    private static final ObjectMapper JSON = new ObjectMapper();
    15	    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
    16	    private static final Pattern MONTH = Pattern.compile("\\d{4}-\\d{2}");
    17	    private static final String CSV = "text/csv; charset=utf-8";
    18	
    19	    private final ReservationService service;
    20	    private final Reports reports;
    21	
    22	    public Api(ReservationService service, Reports reports) {
    23	        this.service = service;
    24	        this.reports = reports;
    25	    }
    26	
    27	    record RoomView(int number, RoomType type, int capacity, BigDecimal nightlyRate) {}
    28	
    29	    record ReservationView(long id, int roomNumber, String guestName, String guestEmail, String guestCpf,
    30	            String companyCnpj, String companyName, String guestPassport, String guestCountry, String checkIn,
    31	            String checkOut, int guests, RatePlan ratePlan, int nights, BigDecimal subtotal, BigDecimal discount,
    32	            BigDecimal total, Status status, BigDecimal amountPaid, BigDecimal refund) {
    33	        static ReservationView of(Reservation r) {
    34	            Identification i = r.identification();
    35	            return new ReservationView(r.id(), r.roomNumber(), r.guestName(), r.guestEmail(), i.cpf(), i.cnpj(),
    36	                    i.companyName(), i.passport(), i.country(), r.checkIn().toString(), r.checkOut().toString(),
    37	                    r.guests(), r.ratePlan(), r.nights(), r.subtotal(), r.discount(), r.total(), r.status(),
    38	                    r.amountPaid(), r.refund());
    39	        }
    40	    }
    41	
    42	    public Javalin start(int port) {
    43	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
    44	        app.get("/rooms", ctx -> ctx.json(Room.ALL.stream()
    45	                .map(r -> new RoomView(r.number(), r.type(), r.capacity(), r.type().nightlyRate)).toList()));
    46	        app.post("/reservations", ctx -> ctx.status(201).json(ReservationView.of(service.create(parse(ctx)))));
    47	        app.get("/reservations/{id}", ctx -> ctx.json(ReservationView.of(service.get(id(ctx)))));
    48	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(ReservationView.of(service.confirm(id(ctx)))));
    49	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(ReservationView.of(service.cancel(id(ctx)))));
    50	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(ReservationView.of(service.checkIn(id(ctx)))));
    51	        app.post("/reservations/{id}/check-out", ctx -> {
    52	            long id = id(ctx);
    53	            service.checkOut(id);
    54	            ctx.json(service.document(id));
    55	        });
    56	        app.get("/reservations/{id}/document", ctx -> ctx.json(service.document(id(ctx))));
    57	        app.get("/messages", ctx -> ctx.json(service.messages()));
    58	        app.get("/reports/occupancy", ctx -> ctx.contentType(CSV).result(reports.occupancy(
    59	                date(ctx.queryParam("date"), "date"))));
    60	        app.get("/reports/revenue", ctx -> ctx.contentType(CSV).result(reports.revenue(month(ctx.queryParam("month")))));
    61	
    62	        app.exception(ApiException.class, (e, ctx) ->
    63	                ctx.status(e.status).json(Map.of("error", e.code, "message", e.getMessage())));
    64	        app.exception(Exception.class, (e, ctx) -> {
    65	            e.printStackTrace();
    66	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", "Erro interno"));
    67	        });
    68	        return app.start(port);
    69	    }
    70	
    71	    private static long id(Context ctx) {
    72	        try {
    73	            return Long.parseLong(ctx.pathParam("id"));
    74	        } catch (NumberFormatException e) {
    75	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
    76	        }
    77	    }
    78	
    79	    private static ReservationService.NewReservation parse(Context ctx) {
    80	        JsonNode b;
    81	        try {
    82	            b = JSON.readTree(ctx.body());
    83	        } catch (Exception e) {
    84	            throw ApiException.invalid("Corpo da requisição não é um JSON válido");
    85	        }
    86	        if (b == null || !b.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON");
    87	
    88	        String name = required(b, "guestName");
    89	        String email = required(b, "guestEmail");
    90	        JsonNode room = b.get("roomNumber");
    91	        if (room == null || !room.isIntegralNumber() || !room.canConvertToInt()) {
    92	            throw ApiException.invalid("roomNumber inválido");
    93	        }
    94	        LocalDate in = date(required(b, "checkIn"), "checkIn");
    95	        LocalDate out = date(required(b, "checkOut"), "checkOut");
    96	        if (!out.isAfter(in)) throw ApiException.invalid("A saída deve ser depois da entrada");
    97	        JsonNode g = b.get("guests");
    98	        if (g == null || !g.isIntegralNumber() || !g.canConvertToInt() || g.asInt() < 1) {
    99	            throw ApiException.invalid("É preciso pelo menos um hóspede");
   100	        }
   101	        RatePlan plan;
   102	        try {
   103	            plan = RatePlan.valueOf(required(b, "ratePlan"));
   104	        } catch (IllegalArgumentException e) {
   105	            throw ApiException.invalid("ratePlan inválido");
   106	        }
   107	        return new ReservationService.NewReservation(room.asInt(), name, email, identification(b), in, out,
   108	                g.asInt(), plan);
   109	    }
   110	
   111	    private static Identification identification(JsonNode b) {
   112	        String cpf = optional(b, "guestCpf");
   113	        String cnpj = optional(b, "companyCnpj");
   114	        String company = optional(b, "companyName");
   115	        String passport = optional(b, "guestPassport");
   116	        String country = optional(b, "guestCountry");
   117	        boolean isCpf = cpf != null;
   118	        boolean isCompany = cnpj != null || company != null;
   119	        boolean isForeign = passport != null || country != null;
   120	        if ((isCpf ? 1 : 0) + (isCompany ? 1 : 0) + (isForeign ? 1 : 0) != 1) {
   121	            throw ApiException.invalid("Informe só uma identificação: CPF, CNPJ com razão social, ou passaporte com país");
   122	        }
   123	        if (isCpf) return new Identification.Cpf(cpf);
   124	        if (isCompany) {
   125	            if (cnpj == null || company == null) throw ApiException.invalid("Informe companyCnpj e companyName");
   126	            return new Identification.Cnpj(cnpj, company);
   127	        }
   128	        if (passport == null || country == null) throw ApiException.invalid("Informe guestPassport e guestCountry");
   129	        return new Identification.Passport(passport, country);
   130	    }
   131	
   132	    private static String optional(JsonNode b, String field) {
   133	        JsonNode n = b.get(field);
   134	        if (n == null || n.isNull()) return null;
   135	        if (!n.isTextual()) throw ApiException.invalid(field + " deve ser texto");
   136	        return n.asText().isBlank() ? null : n.asText();
   137	    }
   138	
   139	    private static String required(JsonNode b, String field) {
   140	        String v = optional(b, field);
   141	        if (v == null) throw ApiException.invalid("Campo obrigatório ausente: " + field);
   142	        return v;
   143	    }
   144	
   145	    private static LocalDate date(String v, String field) {
   146	        if (v == null || !DATE.matcher(v).matches()) throw ApiException.invalid("Data inválida em " + field);
   147	        try {
   148	            return LocalDate.parse(v);
   149	        } catch (Exception e) {
   150	            throw ApiException.invalid("Data inválida em " + field);
   151	        }
   152	    }
   153	
   154	    private static YearMonth month(String v) {
   155	        if (v == null || !MONTH.matcher(v).matches()) throw ApiException.invalid("Mês inválido");
   156	        try {
   157	            return YearMonth.parse(v);
   158	        } catch (Exception e) {
   159	            throw ApiException.invalid("Mês inválido");
   160	        }
   161	    }
   162	}
