     1	package pousada;
     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	import java.sql.Connection;
     6	import java.sql.SQLException;
     7	import java.sql.Statement;
     8	import javax.sql.DataSource;
     9	
    10	public final class Database {
    11	    private Database() {}
    12	
    13	    /** Conecta (esperando o banco subir, se preciso) e cria o esquema. */
    14	    public static DataSource connect(String url, String user, String password) {
    15	        HikariConfig cfg = new HikariConfig();
    16	        cfg.setJdbcUrl(url);
    17	        cfg.setUsername(user);
    18	        cfg.setPassword(password);
    19	        cfg.setMaximumPoolSize(10);
    20	        cfg.setInitializationFailTimeout(-1);
    21	        HikariDataSource ds = new HikariDataSource(cfg);
    22	        SQLException last = null;
    23	        for (int i = 0; i < 60; i++) {
    24	            try (Connection c = ds.getConnection()) {
    25	                createSchema(c);
    26	                return ds;
    27	            } catch (SQLException e) {
    28	                last = e;
    29	                try {
    30	                    Thread.sleep(1000);
    31	                } catch (InterruptedException ie) {
    32	                    Thread.currentThread().interrupt();
    33	                    break;
    34	                }
    35	            }
    36	        }
    37	        throw new IllegalStateException("Banco de dados indisponível", last);
    38	    }
    39	
    40	    private static void createSchema(Connection c) throws SQLException {
    41	        try (Statement s = c.createStatement()) {
    42	            // serializa a criação caso várias instâncias subam juntas
    43	            s.execute("SELECT pg_advisory_lock(727001)");
    44	            try {
    45	                s.execute("""
    46	                        CREATE TABLE IF NOT EXISTS reservations (
    47	                            id BIGSERIAL PRIMARY KEY,
    48	                            room_number INT NOT NULL,
    49	                            guest_name TEXT NOT NULL,
    50	                            guest_email TEXT NOT NULL,
    51	                            guest_cpf TEXT,
    52	                            company_cnpj TEXT,
    53	                            company_name TEXT,
    54	                            guest_passport TEXT,
    55	                            guest_country TEXT,
    56	                            check_in DATE NOT NULL,
    57	                            check_out DATE NOT NULL,
    58	                            guests INT NOT NULL,
    59	                            rate_plan TEXT NOT NULL,
    60	                            nights INT NOT NULL,
    61	                            subtotal NUMERIC(12,2) NOT NULL,
    62	                            discount NUMERIC(12,2) NOT NULL,
    63	                            total NUMERIC(12,2) NOT NULL,
    64	                            status TEXT NOT NULL,
    65	                            amount_paid NUMERIC(12,2) NOT NULL,
    66	                            refund NUMERIC(12,2)
    67	                        )""");
    68	                s.execute("CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in, check_out)");
    69	                s.execute("""
    70	                        CREATE TABLE IF NOT EXISTS messages (
    71	                            id BIGSERIAL PRIMARY KEY,
    72	                            channel TEXT NOT NULL,
    73	                            recipient TEXT NOT NULL,
    74	                            subject TEXT NOT NULL,
    75	                            body TEXT NOT NULL
    76	                        )""");
    77	            } finally {
    78	                s.execute("SELECT pg_advisory_unlock(727001)");
    79	            }
    80	        }
    81	    }
    82	}
