     5	/**
     6	 * Como o hóspede se identifica. Cada forma define o documento que ele recebe;
     7	 * um novo tipo (ex.: agência de turismo) basta implementar esta interface.
     8	 */
     9	public sealed interface Identification permits Identification.Cpf, Identification.Cnpj, Identification.Passport {
    10	
    11	    String title();
    12	
    13	    /** Texto completo do documento. */
    14	    String render(Reservation r);
    15	
    16	    default String cpf() { return null; }
    17	    default String cnpj() { return null; }
    18	    default String companyName() { return null; }
    19	    default String passport() { return null; }
    20	    default String country() { return null; }
    21	
    22	    private static String stay(Reservation r) {
    23	        return "Entrada: " + Dates.pt(r.checkIn()) + " | Saída: " + Dates.pt(r.checkOut()) + " | "
    24	                + r.nights() + (r.nights() == 1 ? " diária" : " diárias");
    25	    }
    26	
    27	    private static String body(Reservation r) {
    28	        StringBuilder sb = new StringBuilder();
    29	        sb.append("Quarto: ").append(r.roomNumber()).append(" (").append(r.roomType()).append(")\n");
    30	        sb.append(stay(r)).append('\n');
    31	        sb.append("Diárias: ").append(Money.pt(r.subtotal())).append('\n');
    32	        if (r.discount().signum() > 0) sb.append("Desconto: ").append(Money.pt(r.discount())).append('\n');
    33	        sb.append("Total: ").append(Money.pt(r.total()));
    34	        return sb.toString();
    35	    }
    36	
    37	    record Cpf(String number) implements Identification {
    38	        public String title() { return "Comprovante de reserva"; }
