554	    12	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
555	    13	
556	    14	    /** Alta temporada: de 15/12 ao fim de fevereiro e todo o mês de julho. */
557	    15	    public static boolean isHighSeason(LocalDate night) {
558	    16	        int m = night.getMonthValue();
559	    17	        return m == 1 || m == 2 || m == 7 || (m == 12 && night.getDayOfMonth() >= 15);
560	    18	    }
561	    19	
562	    20	    public static BigDecimal nightPrice(RoomType type, LocalDate night) {
563	    21	        return isHighSeason(night) ? Money.round(type.nightlyRate.multiply(HIGH_SEASON_FACTOR)) : type.nightlyRate;
564	    22	    }
565	    23	
566	    24	    /** Noites de checkIn (inclusive) até checkOut (exclusive). */
567	    25	    public static Quote quote(RoomType type, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
568	    26	        BigDecimal subtotal = Money.ZERO;
569	    27	        int nights = 0;
570	    28	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
571	    29	            subtotal = subtotal.add(nightPrice(type, d));
572	    30	            nights++;
573	    31	        }
574	    32	        subtotal = Money.round(subtotal);
575	    33	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
576	    34	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT)) : Money.ZERO;
577	    35	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
578	    36	    }
