    59	                date(ctx.queryParam("date"), "date"))));
    60	        app.get("/reports/revenue", ctx -> ctx.contentType(CSV).result(reports.revenue(month(ctx.queryParam("month")))));
    61	
    62	        app.exception(ApiException.class, (e, ctx) ->
