   104	        } catch (IllegalArgumentException e) {
   105	            throw ApiException.invalid("ratePlan inválido");
   106	        }
   107	        return new ReservationService.NewReservation(room.asInt(), name, email, identification(b), in, out,
   108	                g.asInt(), plan);
