   115	        String passport = optional(b, "guestPassport");
   116	        String country = optional(b, "guestCountry");
   117	        boolean isCpf = cpf != null;
   118	        boolean isCompany = cnpj != null || company != null;
   119	        boolean isForeign = passport != null || country != null;
   120	        if ((isCpf ? 1 : 0) + (isCompany ? 1 : 0) + (isForeign ? 1 : 0) != 1) {
   121	            throw ApiException.invalid("Informe só uma identificação: CPF, CNPJ com razão social, ou passaporte com país");
   122	        }
   123	        if (isCpf) return new Identification.Cpf(cpf);
   124	        if (isCompany) {
