     1	package pousada;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	public final class Pricing {
     7	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     8	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
     9	
    10	    private Pricing() {}
    11	
    12	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    13	
    14	    /** Alta temporada: de 15/12 ao fim de fevereiro e todo o mês de julho. */
    15	    public static boolean isHighSeason(LocalDate night) {
    16	        int m = night.getMonthValue();
    17	        return m == 1 || m == 2 || m == 7 || (m == 12 && night.getDayOfMonth() >= 15);
    18	    }
    19	
    20	    public static BigDecimal nightPrice(RoomType type, LocalDate night) {
    21	        return isHighSeason(night) ? Money.round(type.nightlyRate.multiply(HIGH_SEASON_FACTOR)) : type.nightlyRate;
    22	    }
    23	
    24	    /** Noites de checkIn (inclusive) até checkOut (exclusive). */
    25	    public static Quote quote(RoomType type, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    26	        BigDecimal subtotal = Money.ZERO;
    27	        int nights = 0;
    28	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    29	            subtotal = subtotal.add(nightPrice(type, d));
    30	            nights++;
    31	        }
    32	        subtotal = Money.round(subtotal);
    33	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    34	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT)) : Money.ZERO;
    35	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    36	    }
    37	}
