     7	public class ReservationService {
     8	    static final String SUBJECT = "Reserva confirmada - Pousada Maré Alta";
     9	
    10	    private final Store store;
    11	
    12	    public ReservationService(Store store) {
    13	        this.store = store;
    14	    }
    15	
    16	    public record NewReservation(int roomNumber, String guestName, String guestEmail, Identification identification,
    17	            LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
    18	
    19	    public Reservation create(NewReservation n) {
    20	        Room room = Room.find(n.roomNumber())
    21	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto não encontrado: " + n.roomNumber()));
    22	        if (n.guests() > room.capacity()) {
    23	            throw new ApiException(422, "CAPACITY_EXCEEDED",
    24	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    25	        }
    26	        Pricing.Quote q = Pricing.quote(room.type(), n.checkIn(), n.checkOut(), n.ratePlan());
    27	        return store.tx(c -> {
    28	            store.lockRoom(c, room.number());
    29	            if (store.isRoomBusy(c, room.number(), n.checkIn(), n.checkOut())) {
    30	                throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
    31	            }
    32	            return store.insert(c, new Reservation(0, room.number(), n.guestName(), n.guestEmail(),
    33	                    n.identification(), n.checkIn(), n.checkOut(), n.guests(), n.ratePlan(), q.nights(),
    34	                    q.subtotal(), q.discount(), q.total(), Status.PENDING, Money.ZERO, null));
    35	        });
    36	    }
    37	
    38	    public Reservation get(long id) {
    39	        return store.tx(c -> store.find(c, id, false).orElseThrow(ReservationService::notFound));
    40	    }
    41	
    42	    public Reservation confirm(long id) {
    43	        return store.tx(c -> {
    44	            Reservation r = load(c, id);
    45	            require(r.status() == Status.PENDING, "Só é possível confirmar uma reserva pendente");
    46	            store.updateState(c, id, Status.CONFIRMED, r.total(), null);
    47	            Reservation paid = load(c, id);
    48	            store.addMessage(c, new Message(0, "EMAIL", paid.guestEmail(), SUBJECT, confirmationBody(paid)));
    49	            return paid;
    50	        });
    51	    }
    52	
    53	    public Reservation checkIn(long id) {
    54	        return transition(id, Status.CONFIRMED, Status.CHECKED_IN, "Só é possível fazer check-in de uma reserva confirmada");
    55	    }
    56	
    57	    public Reservation checkOut(long id) {
    58	        return transition(id, Status.CHECKED_IN, Status.CHECKED_OUT,
    59	                "Só é possível fazer check-out de uma reserva com check-in");
    60	    }
    61	
    62	    public Reservation cancel(long id) {
    63	        return store.tx(c -> {
    64	            Reservation r = load(c, id);
    65	            require(r.status() == Status.PENDING || r.status() == Status.CONFIRMED,
    66	                    "Só é possível cancelar uma reserva pendente ou confirmada");
    67	            BigDecimal refund = r.ratePlan() == RatePlan.STANDARD ? r.amountPaid() : Money.ZERO;
    68	            store.updateState(c, id, Status.CANCELLED, r.amountPaid(), refund);
    69	            return load(c, id);
    70	        });
    71	    }
    72	
    73	    /** Segunda via: só existe para reserva paga. */
    74	    public Document document(long id) {
    75	        Reservation r = get(id);
    76	        require(r.status().isPaid(), "Só há documento para reserva paga");
    77	        return Document.of(r);
    78	    }
    79	
    80	    public List<Message> messages() {
    81	        return store.tx(store::messages);
    82	    }
    83	
    84	    private Reservation transition(long id, Status from, Status to, String error) {
    85	        return store.tx(c -> {
    86	            Reservation r = load(c, id);
    87	            require(r.status() == from, error);
    88	            store.updateState(c, id, to, r.amountPaid(), r.refund());
    89	            return load(c, id);
    90	        });
    91	    }
    92	
    93	    private Reservation load(java.sql.Connection c, long id) throws java.sql.SQLException {
    94	        return store.find(c, id, true).orElseThrow(ReservationService::notFound);
    95	    }
    96	
    97	    private static void require(boolean ok, String message) {
    98	        if (!ok) throw ApiException.notAllowed(message);
    99	    }
   100	
   101	    private static ApiException notFound() {
   102	        return new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
   103	    }
   104	
   105	    static String confirmationBody(Reservation r) {
   106	        return "Olá, " + r.guestName() + "!\n\n"
   107	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
   108	                + r.identification().render(r) + "\n\n"
   109	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   110	                + "Até breve!";
   111	    }
   112	}
