 3	import static org.junit.jupiter.api.Assertions.assertEquals;
 4	
 5	import java.time.LocalDate;
 6	import org.junit.jupiter.api.Test;
 7	
 8	class PricingAndDocumentTest {
 9	    private static Reservation res(long id, int room, String name, Identification i, String in, String out,
10	            RatePlan plan) {
11	        LocalDate a = LocalDate.parse(in), b = LocalDate.parse(out);
12	        Pricing.Quote q = Pricing.quote(Room.find(room).orElseThrow().type(), a, b, plan);
13	        return new Reservation(id, room, name, "x@y.z", i, a, b, 2, plan, q.nights(), q.subtotal(), q.discount(),
14	                q.total(), Status.CONFIRMED, q.total(), null);
15	    }
16	
17	    @Test
18	    void highSeasonPricing() {
19	        var q = Pricing.quote(RoomType.STANDARD, LocalDate.parse("2027-07-10"), LocalDate.parse("2027-07-12"),
20	                RatePlan.STANDARD);
21	        assertEquals(Money.of("599.76"), q.total());
22	        assertEquals(2, q.nights());
23	    }
24	
25	    @Test
26	    void seasonBoundaries() {
27	        assertEquals(false, Pricing.isHighSeason(LocalDate.parse("2027-12-14")));
28	        assertEquals(true, Pricing.isHighSeason(LocalDate.parse("2027-12-15")));
29	        assertEquals(true, Pricing.isHighSeason(LocalDate.parse("2028-02-29")));
30	        assertEquals(false, Pricing.isHighSeason(LocalDate.parse("2028-03-01")));
31	    }
32	
33	    @Test
34	    void nonRefundableDiscountRoundsHalfEven() {
35	        var q = Pricing.quote(RoomType.DELUXE, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"),
36	                RatePlan.NON_REFUNDABLE);
37	        assertEquals(Money.of("779.80"), q.subtotal());
38	        assertEquals(Money.of("116.97"), q.discount());
39	        assertEquals(Money.of("662.83"), q.total());
40	    }
41	
42	    @Test
43	    void moneyFormats() {
44	        assertEquals("R$ 1.234,56", Money.pt(Money.of("1234.56")));
45	        assertEquals("BRL 1,234.56", Money.en(Money.of("1234.56")));
46	    }
47	
48	    @Test
49	    void comprovante() {
50	        var r = res(7, 201, "Carla Dias", new Identification.Cpf("111.222.333-44"), "2027-03-10", "2027-03-12",
51	                RatePlan.STANDARD);
52	        assertEquals("""
53	                Comprovante de reserva nº 7
54	                Hóspede: Carla Dias (CPF 111.222.333-44)
55	                Quarto: 201 (DELUXE)
56	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
57	                Diárias: R$ 779,80
58	                Total: R$ 779,80""", r.identification().render(r));
59	    }
60	
61	    @Test
62	    void fatura() {
63	        var r = res(3, 201, "Ana Souza", new Identification.Cnpj("12.345.678/0001-90", "Tecnosul Ltda"),
64	                "2027-03-10", "2027-03-12", RatePlan.STANDARD);
65	        assertEquals("""
66	                Fatura de hospedagem nº 3
67	                Empresa: Tecnosul Ltda (CNPJ 12.345.678/0001-90)
68	                Hóspede: Ana Souza
69	                Quarto: 201 (DELUXE)
70	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
71	                Diárias: R$ 779,80
72	                Total: R$ 779,80
73	                ISS retido (5%): R$ 38,99""", r.identification().render(r));
74	    }
75	
76	    @Test
77	    void bookingReceiptWithDiscountOneNight() {
78	        var r = res(4, 201, "John Smith", new Identification.Passport("X1234567", "United Kingdom"),
79	                "2027-03-10", "2027-03-11", RatePlan.NON_REFUNDABLE);
80	        assertEquals("""
81	                Booking receipt no. 4
82	                Guest: John Smith (passport X1234567, United Kingdom)
83	                Room: 201 (DELUXE)
84	                Check-in: 2027-03-10 | Check-out: 2027-03-11 | 1 night
85	                Nights: BRL 389.90
86	                Discount: BRL 58.48
87	                Total: BRL 331.42""", r.identification().render(r));
88	    }
89	
90	    @Test
91	    void emailBody() {
92	        var r = res(7, 201, "Carla Dias", new Identification.Cpf("111.222.333-44"), "2027-03-10", "2027-03-12",
93	                RatePlan.STANDARD);
94	        String body = ReservationService.confirmationBody(r);
95	        assertEquals(true, body.startsWith("Olá, Carla Dias!\n\nSua reserva na Pousada Maré Alta está confirmada."
96	                + " Estes são os dados dela:\n\nComprovante de reserva nº 7\n"));
97	        assertEquals(true, body.endsWith("Total: R$ 779,80\n\nA entrada é a partir das 14h, e a saída, até as 12h.\nAté breve!"));
98	    }
99	}

